pairs.typebox:
import Type from "typebox";
import { defineChecks } from "measuretwice";

export const memorySupported = defineChecks({
  version: 1,
  name: "memory-supported",
  inputs: Type.Object({
    text: Type.String({ minLength: 1, description: "The proposed memory text" }),
  }, { additionalProperties: false }),
  checks: [
    {
      id: "text-length",
      name: "The memory fits the length limit",
      using: ["text"],
      rule: { maxLength: 10 },
    },
  ],
});

import Type from "typebox";
import { defineChecks } from "measuretwice";

export const consequenceLevel = defineChecks({
  version: 1,
  name: "consequence-level",
  inputs: Type.Object({
    prior_decision: Type.String({ minLength: 1 }),
    conversation: Type.String({ minLength: 1 }),
    proposed_message: Type.String({ minLength: 1 }),
  }, { additionalProperties: false }),
  checks: [
    {
      id: "consequence",
      name: "The concern warrants an interruption",
      using: ["prior_decision", "conversation", "proposed_message"],
      question: "What consequence does this concern have, based on the evidence?",
      scale: [
        { minor: "A wording or preference difference with no identified operational consequence." },
        { meaningful: "A coordination problem causing rework or delay." },
        { serious: "A conflict affecting an explicit customer commitment or operational requirement." },
      ],
      accept: { at_least: "meaningful" },
    },
  ],
});

import Type from "typebox";
import { defineChecks } from "measuretwice";

export const releaseNotesReview = defineChecks({
  version: 1,
  name: "release-notes-review",
  inputs: Type.Object({
    summary: Type.String({ minLength: 1, maxLength: 200 }),
    severity: Type.Integer({ minimum: 1, maximum: 5 }),
    confidence: Type.Number({ minimum: 0, maximum: 1 }),
    breaking: Type.Boolean(),
    tickets: Type.Array(Type.String({ minLength: 1 }), { minItems: 1, maxItems: 50 }),
    metadata: Type.Object({
      team: Type.String({ minLength: 1 }),
      area: Type.Optional(Type.String({ minLength: 1 })),
    }, { additionalProperties: false }),
  }, { additionalProperties: false }),
  checks: [
    {
      id: "notes-complete",
      name: "The release notes identify the owning team",
      using: ["summary", "metadata"],
      question: "Do the notes name the team that owns the change?",
      answers: {
        yes: "The notes name the owning team.",
        no: "The notes do not name the owning team.",
      },
      accept: "yes",
    },
    {
      id: "summary-free-of-todos",
      name: "The summary carries no open work marker",
      using: ["summary"],
      rule: { excludes: "TODO" },
    },
  ],
});
